// CONTRATO DE SALIDA DEL WORKER
// Devuelve SIEMPRE un objeto JSON limpio y predecible al Manager,
// incluso ante fallos. Nunca arrastra el payload masivo de la planilla.

try {
  const params = $('Execute Workflow Trigger').first().json;
  const numero = (params.numero_pedido || '').toString().trim().toUpperCase();

  if (!numero) {
    return [{ json: {
      status: 'error',
      codigo: 'PARAM_FALTANTE',
      mensaje: 'El Manager no envio el campo numero_pedido',
      data: {}
    }}];
  }

  const filas = $input.all().map(i => i.json);
  const pedido = filas.find(f =>
    (f.numero_pedido || '').toString().trim().toUpperCase() === numero
  );

  if (!pedido) {
    return [{ json: {
      status: 'not_found',
      codigo: 'PEDIDO_INEXISTENTE',
      mensaje: `No existe ningun pedido con el numero ${numero}`,
      data: {}
    }}];
  }

  return [{ json: {
    status: 'success',
    codigo: 'OK',
    mensaje: 'Pedido recuperado correctamente',
    data: {
      numero_pedido: pedido.numero_pedido,
      nombre_cliente: pedido.nombre_cliente,
      producto: pedido.producto,
      estado: pedido.estado,
      fecha_estimada_entrega: pedido.fecha_estimada_entrega,
      transportista: pedido.transportista,
      numero_seguimiento: pedido.numero_seguimiento,
      monto_total: pedido.monto_total
    }
  }}];

} catch (e) {
  // Contingencia: el Worker nunca muere en silencio.
  // Si explota, igual devuelve un JSON estructurado para que el Manager no se bloquee.
  return [{ json: {
    status: 'error',
    codigo: 'FALLO_INTERNO_WORKER',
    mensaje: e.message,
    data: {}
  }}];
}
